using GraphApi.Models.TKT.EstadosTickets;namespace GraphApi.Services.TKT.EstadosTickets{    /// <summary>    /// Define las operaciones de negocio y persistencia para EstadosTickets.    /// </summary>    public interface IEstadosTicketsService    {        /// <summary>        /// Obtiene la lista de EstadosTickets con filtros opcionales.        /// </summary>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<clReadEstadosTickets>> GetEstadosTickets(            int userId,            string windowName);        /// <summary>        /// Obtiene la lista dinámica de EstadosTickets con filtros opcionales.        /// </summary>        /// <param name="estadoTicketID">Filtro opcional para EstadoTicketID.</param>        /// <param name="estadoTicket">Filtro opcional para EstadoTicket.</param>        /// <param name="bEliminado">Filtro opcional para bEliminado.</param>        /// <param name="columnNames">Nombres de columnas a retornar (separados por coma). Si es null o vacío, retorna columna por defecto.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<dynamic>> GetEstadosTicketsDynamic(            int? estadoTicketID,            string? estadoTicket,            bool? bEliminado,            string? columnNames,            int userId,            string windowName);        /// <summary>        /// Crea un nuevo EstadosTicket.        /// </summary>        /// <param name="objInput">Datos para crear el EstadosTicket.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadEstadosTickets> CreateEstadosTickets(            clCreateEstadosTickets objInput,            int userId,            string windowName);        /// <summary>        /// Actualiza campos selectivos de un EstadosTicket.        /// </summary>        /// <param name="objInput">Datos para actualizar el EstadosTicket, incluyendo su ID y campos a modificar.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadEstadosTickets?> UpdateEstadosTickets(            clUpdateEstadosTickets objInput,            int userId,            string windowName);        /// <summary>        /// Elimina un EstadosTicket por su ID.        /// </summary>        /// <param name="nEstadosTicketsID">ID del EstadosTicket a eliminar.</param>        Task<bool> DeleteEstadosTickets(int nEstadosTicketsID);    }}